    """Czech aware time frame format function, takes into account
    the differences between past and future forms."""
    positive_delta = abs(delta)
    base_template = self.timeframes[timeframe]

    if isinstance(base_template, str):
        return base_template.format(positive_delta)

    key_selection = None
    if delta == 0:
        key_selection = "zero"  # And *never* use 0 in the singular!
    elif delta < 0:
        key_selection = "past"
    else:
        # Needed since both regular future and future-singular and future-paucal cases
        has_future_singular_key = "future-singular" in base_template
        if not has_future_singular_key:
            key_selection = "future"
        else:
            mod_10 = positive_delta % 10
            mod_100 = positive_delta % 100
            if 2 <= mod_10 <= 4 and (mod_100 < 10 or mod_100 >= 20):
                key_selection = "future-singular"
            else:
                key_selection = "future-paucal"

    final_template: str = base_template[key_selection]
    return final_template.format(positive_delta)"
