    {
        "qualname": "arrow/locales.py::HebrewLocale.describe_multi",
        "source": "def describe_multi(
    self,
    timeframes: Sequence[Tuple[TimeFrameLiteral, Union[int, float]]],
    only_distance: bool = False,
) -> str:
    """Describes a delta within multiple timeframes in plain language.
    In Hebrew, the and word behaves a bit differently.

    :param timeframes: a list of string, quantity pairs each representing a timeframe and delta.
    :param only_distance: return only distance eg: "2 hours and 11 seconds" without "in" or "ago" keywords
    """
    accumulated_text = ""
    total_items = len(timeframes)

    for index, (current_timeframe, current_delta) in enumerate(timeframes):
        truncated_delta = trunc(current_delta)
        formatted_segment = self._format_timeframe(current_timeframe, truncated_delta)

        if index == 0:
            accumulated_text = formatted_segment
        elif index == total_items - 1:  # Must have at least 2 items
            accumulated_text += " " + self.and_word
            first_char_is_digit = formatted_segment[0].isdecimal()
            if first_char_is_digit:
                accumulated_text += "\u05be"
            accumulated_text += formatted_segment
        else:  # Don't add for the last one
            accumulated_text += ", " + formatted_segment

    if not only_distance:
        last_timeframe = timeframes[-1][0] if timeframes else timeframe
        last_delta_val = timeframes[-1][1] if timeframes else 0
        accumulated_text = self._format_relative(
            accumulated_text, last_timeframe, trunc(last_delta_val)
        )

    return accumulated_text"
