        "qualname": "arrow/locales.py::ThaiLocale._format_relative",
        "source": "def _format_relative(
    self,
    humanized: str,
    timeframe: TimeFrameLiteral,
    delta: Union[float, int],
) -> str:
    """Thai normally doesn't have any space between words"""
    if timeframe == "now":
        return humanized

    direction_template = self.past if delta < 0 else self.future
    relative_output = direction_template.format(humanized)

    if timeframe == "seconds":
        relative_output = relative_output.replace(" ", "")

    return relative_output"
