        "qualname": "arrow/parser.py::DateTimeParser._parse_token",
        "source": "def _parse_token(
    self,
    token: Any,
    value: Any,
    parts: _Parts,
) -> None:

    if token == "YYYY":
        parts["year"] = int(value)

    elif token == "YY":
        numeric_value = int(value)
        if numeric_value > 68:
            parts["year"] = 1900 + numeric_value
        else:
            parts["year"] = 2000 + numeric_value

    elif token in ["MMMM", "MMM"]:
        # FIXME: month_number() is nullable
        lower_value = value.lower()
        month_index = self.locale.month_number(lower_value)  # type: ignore
        parts["month"] = month_index

    elif token in ["MM", "M"]:
        parts["month"] = int(value)

    elif token in ["DDDD", "DDD"]:
        parts["day_of_year"] = int(value)

    elif token in ["DD", "D"]:
        parts["day"] = int(value)

    elif token == "Do":
        parts["day"] = int(value)

    elif token == "dddd":
        # locale day names are 1-indexed
        lower_value = value.lower()
        normalized_day_names = [x.lower() for x in self.locale.day_names]
        found_index = normalized_day_names.index(lower_value)
        parts["day_of_week"] = found_index - 1

    elif token == "ddd":
        # locale day abbreviations are 1-indexed
        lower_value = value.lower()
        normalized_abbrs = [x.lower() for x in self.locale.day_abbreviations]
        found_index = normalized_abbrs.index(lower_value)
        parts["day_of_week"] = found_index - 1

    elif token.upper() in ["HH", "H"]:
        parts["hour"] = int(value)

    elif token in ["mm", "m"]:
        parts["minute"] = int(value)

    elif token in ["ss", "s"]:
        parts["second"] = int(value)

    elif token == "S":
        # We have the *most significant* digits of an arbitrary-precision integer.
        # We want the six most significant digits as an integer, rounded.
        # IDEA: add nanosecond support somehow? Need datetime support for it first.
        padded_value = value.ljust(7, "0")

        # floating-point (IEEE-754) defaults to half-to-even rounding
        seventh_digit = int(padded_value[6])
        if seventh_digit == 5:
            fifth_digit = int(padded_value[5])
            rounding_adjustment = fifth_digit % 2
        elif seventh_digit > 5:
            rounding_adjustment = 1
        else:
            rounding_adjustment = 0

        base_microseconds = int(padded_value[:6])
        parts["microsecond"] = base_microseconds + rounding_adjustment

    elif token == "X":
        parts["timestamp"] = float(value)

    elif token == "x":
        parts["expanded_timestamp"] = int(value)

    elif token in ["ZZZ", "ZZ", "Z"]:
        parts["tzinfo"] = TzinfoParser.parse(value)

    elif token in ["a", "A"]:
        am_values = (self.locale.meridians["am"], self.locale.meridians["AM"])
        pm_values = (self.locale.meridians["pm"], self.locale.meridians["PM"])

        if value in am_values:
            parts["am_pm"] = "am"
            if "hour" in parts:
                hour_val = parts["hour"]
                if not (0 <= hour_val <= 12):
                    raise ParserMatchError(
                        f"Hour token value must be between 0 and 12 inclusive for token {token!r}."
                    )
        elif value in pm_values:
            parts["am_pm"] = "pm"
    elif token == "W":
        parts["weekdate"] = value"
