   def _format_relative(
       self,
       display_text: str,
       period_type: TimeFrameLiteral,
       time_diff: Union[float, int],
   ) -> str:
       """Thai normally doesn't have any space between words"""
       if period_type == "now":
           return display_text

       temporal_direction = self.past if time_diff < 0 else self.future
       formatted_output = temporal_direction.format(display_text)

       if period_type == "seconds":
           formatted_output = formatted_output.replace(" ", "")

       return formatted_output
